package com.desktodo.app;
import org.json.*;import java.time.*;import java.util.*;
/** Portable, data-only extensions. Templates never carry tasks, credentials or device addresses. */
final class DeskExtras {
 static final String[] VISUAL={"layout","ratio","scene","cardsVersion","card1","card2","weeklyGoal","note","deskStatus","statusNote"};
 static JSONObject template(JSONObject cfg,String name)throws Exception{String title=name.trim();if(title.isEmpty()||title.length()>30)throw new Exception("模板名称1至30字");JSONObject visual=new JSONObject();for(String k:VISUAL)if(cfg.has(k))visual.put(k,cfg.get(k));validate(visual);return new JSONObject().put("schema","mojian-template-v1").put("name",title).put("settings",visual);}
 static void validate(JSONObject c)throws Exception{if(!Arrays.asList("focus","agenda","minimal","overview","pomodoro","living","custom","calendar").contains(c.optString("layout")))throw new Exception("模板排版不支持");if(c.optInt("ratio",67)<40||c.optInt("ratio",67)>75||c.optInt("weeklyGoal",20)<1||c.optInt("weeklyGoal",20)>999||c.optString("note").length()>100||c.optString("statusNote").length()>30||c.optString("deskStatus").length()>30)throw new Exception("模板参数超出范围");for(String k:new String[]{"card1","card2"})if(c.has(k)&&!Arrays.asList(ScreenData.CARD_KEYS).contains(c.optString(k)))throw new Exception("模板卡片不支持");}
 static JSONObject importTemplate(JSONObject original,JSONObject template)throws Exception{if(!template.optString("schema").equals("mojian-template-v1"))throw new Exception("不是墨间模板v1");JSONObject source=template.getJSONObject("settings");validate(source);JSONObject cfg=DeskModel.copy(original);for(String k:VISUAL)if(source.has(k))cfg.put(k,source.get(k));cfg.put("cardsVersion",1);if(!source.has("scene"))cfg.put("scene",cfg.optString("layout").equals("calendar")?"life":cfg.optString("layout").equals("pomodoro")?"focus":"work");return cfg;}
 static JSONArray addHabit(JSONArray source,String title)throws Exception{title=title.trim();if(title.isEmpty()||title.length()>20)throw new Exception("习惯名称1至20字");if(source.length()>=3)throw new Exception("最多三个习惯，先专注做好小事");JSONArray out=DeskModel.copy(source);out.put(new JSONObject().put("id",UUID.randomUUID().toString()).put("title",title).put("days",new JSONArray()));return out;}
 static JSONArray toggle(JSONArray source,String id,LocalDate day)throws Exception{JSONArray out=DeskModel.copy(source);for(int i=0;i<out.length();i++){JSONObject h=out.getJSONObject(i);if(!h.getString("id").equals(id))continue;JSONArray days=h.optJSONArray("days");Set<String> set=new TreeSet<>();for(int j=0;days!=null&&j<days.length();j++){LocalDate d=LocalDate.parse(days.getString(j));if(!d.isBefore(day.minusDays(55))&&!d.isAfter(day))set.add(d.toString());}if(!set.remove(day.toString()))set.add(day.toString());JSONArray result=new JSONArray();for(String d:set)result.put(d);h.put("days",result);return out;}throw new Exception("习惯已被移除，请重试");}
 static boolean checked(JSONObject h,LocalDate day){JSONArray days=h.optJSONArray("days");for(int i=0;days!=null&&i<days.length();i++)if(days.optString(i).equals(day.toString()))return true;return false;}
 static String habitText(JSONObject cfg,Instant now){JSONArray list=cfg.optJSONArray("habits");if(list==null||list.length()==0)return "先在手机添加\n最多三个小习惯";LocalDate day=now.atZone(ScreenData.ZONE).toLocalDate();StringJoiner out=new StringJoiner("\n");for(int i=0;i<Math.min(3,list.length());i++){JSONObject h=list.optJSONObject(i);out.add((checked(h,day)?"✓ ":"○ ")+h.optString("title"));}return out.toString();}
 static String eventText(JSONObject cfg,Instant now){JSONObject e=cfg.optJSONObject("nextEvent");if(e==null)return "未启用日历\n或未来七天无日程";long begin=e.optLong("begin"),end=e.optLong("end");if(end<=now.toEpochMilli())return "当前日程已结束\n请更新日历";return (e.optBoolean("allDay")?"全天":java.time.format.DateTimeFormatter.ofPattern("MM/dd HH:mm").withZone(ScreenData.ZONE).format(Instant.ofEpochMilli(begin)))+"\n"+e.optString("title");}
 static String commuteText(JSONObject cfg,Instant now){JSONObject c=cfg.optJSONObject("commute");if(c==null)return "先配置通勤路线";if(now.toEpochMilli()-c.optLong("fetched")>900000)return "路况已过期\n请更新通勤";return "驾车约 "+c.optInt("minutes")+" 分钟\n"+c.optString("advice");}
 static JSONObject agentConfig(JSONObject cfg)throws Exception{JSONObject out=new JSONObject();for(String key:new String[]{"layout","ratio","city","latitude","longitude","stocks","stockConfigured","note","weeklyGoal","card1","card2","focusMinutes"})if(cfg.has(key))out.put(key,cfg.get(key));return out;}
 static JSONObject deviceConfig(JSONObject cfg)throws Exception{JSONObject out=new JSONObject();for(String k:new String[]{"layout","ratio","scene","cardsVersion","card1","card2","weeklyGoal","note","deskStatus","statusNote","city","latitude","longitude","stocks","stockConfigured","focusMinutes","focusEnd","focusPaused","focusSession","focusTask","habits","nextEvent","commute","plugin","sharedStats","countdownText"})if(cfg.has(k))out.put(k,cfg.get(k));if(cfg.has("dates")){out.put("countdownText",ScreenData.countdown(cfg,Instant.now()));out.remove("dates");}for(String k:new String[]{"favorites","calendarIDs","calendarEnabled","hubURL","relayCursor"})out.remove(k);JSONArray habits=out.optJSONArray("habits");if(habits!=null){JSONArray compact=new JSONArray();LocalDate day=LocalDate.now(ScreenData.ZONE);for(int i=0;i<Math.min(3,habits.length());i++){JSONObject h=habits.getJSONObject(i);compact.put(new JSONObject().put("id",h.getString("id")).put("title",h.getString("title")).put("days",checked(h,day)?new JSONArray().put(day.toString()):new JSONArray()));}out.put("habits",compact);}return out;}
}
